        inicio_dt, fin_dt, _window_meta = (
            get_operational_datetime_range_for_fecha_operacion(
                unidad_operativa, fecha_actual
            )
        )
        inicio_operativo = inicio_dt.strftime('%Y-%m-%d %H:%M:%S')
        fin_operativo = fin_dt.strftime('%Y-%m-%d %H:%M:%S')
