            fecha_operacion=fecha_actual.strftime('%Y-%m-%d'),
            empresa_id=empresa_sql,
            inicio_operativo=inicio_operativo,
            fin_operativo=fin_operativo,
        ))
        fecha_actual = fecha_siguiente
